# region: render
def render(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs, factor=10):
    return [v * factor for v in xs]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs, factor=10):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(gather(intake(sift(emit(render(raw))))))

