import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 200.0, 'max': 300, 'grade': 'low'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'mean': 850.0, 'max': 1000, 'grade': 'low'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'mean': 650.0, 'max': 800, 'grade': 'low'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 833.3333333333334, 'max': 1200, 'grade': 'low'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'mean': 0.0, 'max': 0, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 600.0, 'max': 600, 'grade': 'high'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'mean': 2100.0, 'max': 4000, 'grade': 'low'})

if __name__ == '__main__':
    unittest.main()
